components.example:
if breeze.AlertDialog(c, &app.confirm, "Delete?", "This cannot be undone.", "Delete", "Cancel") == 0 {
	app.delete()
}

breeze.GridView(c, &app.photos, len(app.thumbs), 140, 120, func(i int) {
	ui.Image(c, app.thumbs[i])
})

breeze.List(c, &app.files, len(app.names), func(i int) {
	ui.Text(c, app.names[i])
})

breeze.Outline(c, &app.files, roots, children, func(path string) {
	ui.Text(c, path)
})

breeze.OutlineTable(c, &app.files, columns, roots, children, func(path string, col int) {
	ui.Text(c, path)
})

breeze.Sidebar(c, &app.mailbox, func() {
	breeze.SidebarSection(c, "Mailboxes", &app.mailboxes, func() {
		breeze.SidebarItem(c, "inbox", inboxIcon, "Inbox")
	})
}).Width(220)

breeze.Table(c, &app.list, columns, len(app.rows), func(row, col int) {
	ui.Text(c, app.rows[row][col])
})

breeze.Toolbar(c, func() {
	breeze.BackButton(c, app.router)
	ui.Spacer(c)
	breeze.Button(c, "Share")
}).Label("Actions")
